    rubrique: "chaine-longue", rubriqueNom: "سلاسل طويلة — عدّة مبرهنات", difficulte: "difficile",
    enonce: "<span dir=\"ltr\" class=\"expr pt\">ABC</span> مثلّث قائم الزاوية في <span dir=\"ltr\" class=\"expr pt\">A</span> حيث <span dir=\"ltr\" class=\"expr pt\">AB = 6</span> و <span dir=\"ltr\" class=\"expr pt\">AC = 8</span>، و <span dir=\"ltr\" class=\"expr pt\">I</span> منتصف <span dir=\"ltr\" class=\"expr pt\">[BC].</span><br><svg class=\"figure\" direction=\"ltr\" viewBox=\"0 0 105 139\" width=\"105\" height=\"139\" xmlns=\"http://www.w3.org/2000/svg\"><g transform=\"translate(-33.1 -24.7)\"><line x1=\"52.8\" y1=\"137.2\" x2=\"116.1\" y2=\"137.2\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"116.1\" y1=\"137.2\" x2=\"52.8\" y2=\"52.8\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"52.8\" y1=\"52.8\" x2=\"52.8\" y2=\"137.2\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"84.4\" y1=\"95.0\" x2=\"52.8\" y2=\"137.2\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><polyline points=\"63.8,137.2 63.8,126.2 52.8,126.2\" fill=\"none\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><line x1=\"97.1\" y1=\"118.5\" x2=\"103.5\" y2=\"113.7\" stroke=\"#c0392b\" stroke-width=\"1.4\"/><line x1=\"65.4\" y1=\"76.3\" x2=\"71.8\" y2=\"71.5\" stroke=\"#c0392b\" stroke-width=\"1.4\"/><circle cx=\"52.8\" cy=\"137.2\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"43.8\" y=\"153.2\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">A</text><circle cx=\"116.1\" cy=\"137.2\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"127.8\" y=\"150.6\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">B</text><circle cx=\"52.8\" cy=\"52.8\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"46.6\" y=\"43.1\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">C</text><circle cx=\"84.4\" cy=\"95.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"93.4\" y=\"87.0\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">I</text></g></svg><br>أحسب المسافة <span dir=\"ltr\" class=\"expr pt\">IA.</span>",
    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">AB = 6</span>  و  <span dir=\"ltr\" class=\"expr pt\">AC = 8</span>  و  <span dir=\"ltr\" class=\"expr pt\">I</span> منتصف <span dir=\"ltr\" class=\"expr pt\">[BC]</span>  و  المثلّث <span dir=\"ltr\" class=\"expr pt\">BAC</span> قائم الزاوية في <span dir=\"ltr\" class=\"expr pt\">A</span>"},{"quoi":"القاعدة","math":"مركز الدائرة المحيطة بالمثلّث القائم هو منتصف وتره"},{"quoi":"نطبّق","math":"المثلّث <span dir=\"ltr\" class=\"expr pt\">BAC</span> قائم الزاوية في <span dir=\"ltr\" class=\"expr pt\">A</span>  و  <span dir=\"ltr\" class=\"expr pt\">I</span> منتصف <span dir=\"ltr\" class=\"expr pt\">[BC]</span>  إذن  النّقط <span dir=\"ltr\" class=\"expr pt\">A</span> و <span dir=\"ltr\" class=\"expr pt\">B</span> و <span dir=\"ltr\" class=\"expr pt\">C</span> تنتمي إلى دائرة مركزها <span dir=\"ltr\" class=\"expr pt\">I</span>"},{"quoi":"القاعدة","math":"نظرية بيتاغور : إذا كان المثلّث قائم الزاوية فمربّع الوتر يساوي مجموع مربّعي الضّلعين الآخرين"},{"quoi":"نطبّق","math":"المثلّث <span dir=\"ltr\" class=\"expr pt\">BAC</span> قائم الزاوية في <span dir=\"ltr\" class=\"expr pt\">A</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB = 6</span>  و  <span dir=\"ltr\" class=\"expr pt\">AC = 8</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BC = 10</span>  ، لأنّ <span dir=\"ltr\" class=\"expr pt\">BC</span>² <span dir=\"ltr\" class=\"expr\">= 6</span>² + 8²"},{"quoi":"القاعدة","math":"منتصف قطعة يقسمها إلى نصفين متقايسين"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">I</span> منتصف <span dir=\"ltr\" class=\"expr pt\">[BC]</span>  و  <span dir=\"ltr\" class=\"expr pt\">BC = 10</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BI = 5</span>  ، أي نصف 10"},{"quoi":"القاعدة","math":"أنصاف أقطار دائرة واحدة متقايسة"},{"quoi":"نطبّق","math":"النّقط <span dir=\"ltr\" class=\"expr pt\">A</span> و <span dir=\"ltr\" class=\"expr pt\">B</span> و <span dir=\"ltr\" class=\"expr pt\">C</span> تنتمي إلى دائرة مركزها <span dir=\"ltr\" class=\"expr pt\">I</span>  و  <span dir=\"ltr\" class=\"expr pt\">BI = 5</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AI = 5</span>  ، لأنّهما نصفا قطر لنفس الدائرة"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">AI = 5</span>"}],
